CREATE TABLE IF NOT EXISTS `rs_shop_transactions` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `identifier` VARCHAR(80) NOT NULL, `shop` VARCHAR(60) NOT NULL, `item` VARCHAR(80) NOT NULL, `quantity` INT UNSIGNED NOT NULL, `amount` INT UNSIGNED NOT NULL, `payment` ENUM('cash','bank') NOT NULL, `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), KEY `identifier_created` (`identifier`,`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
